using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.Modelos;using GraphApi.Services.USR.Modelos;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.Modelos{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Modelos: creación, actualización y eliminación.")]    public class ModelosMutation    {        [Authorize]        [GraphQLName("createModelos")]        [GraphQLDescription("Crea un nuevo Modelo usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadModelos> CreateModelosAsync(            [GraphQLDescription("Datos necesarios para crear el Modelo.")]            clCreateModelos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Modelo.")]            IModelosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateModelos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateModelos")]        [GraphQLDescription("Actualiza los campos especificados de un Modelo existente.")]        public async Task<clReadModelos?> UpdateModelosAsync(            [GraphQLDescription("Datos del Modelo a actualizar.")]            clUpdateModelos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Modelo.")]            IModelosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateModelos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteModelos")]        [GraphQLDescription("Elimina un Modelo por su ID.")]        public async Task<bool> delModelosAsync(            [GraphQLDescription("ID del Modelo a eliminar.")]            int nModelosID,            [Service]            [GraphQLDescription("Servicio para operaciones de Modelo.")]            IModelosService objService        )        {            return await objService.DeleteModelos(nModelosID);        }    }}